const d = $json;
const regions = (d.alertRegions || []).map(r => `- ${r.regionName ?? r.region ?? r}: ${r.level ?? 'RED'} — ${r.totalDetections ?? r.detections ?? '?'} detections · ${Math.round(r.totalFrpMW ?? r.frpMW ?? 0)} MW`).join('\n');
return [{
  json: {
    headline: d.headline || 'IGNIS RED spike detected',
    body: `${d.headline || 'IGNIS RED spike'}\n\n${regions}\n\nCross-checked: ${d.gdacsCrossCheck ?? 'n/a'}\nDashboard: https://ignis-spaceapps2026.vercel.app\nGenerated: ${d.generatedAt ?? new Date().toISOString()}`
  }
}];
